def the_types_of_work(apps, schema_editor):
    WorkType = apps.get_model("crm", "WorkType")
    for position, (key, name_en, name_es, days, in_report, words) in enumerate(TYPES):
        WorkType.objects.get_or_create(key=key, defaults={"name_en": name_en, "name_es": name_es, "days": days,
                                                          "in_revenue_report": in_report, "words": words, "position": position})


